import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const persist = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem(
        "'`${STORAGE_PREFIX}${localID}`,
        JSON.stringify({ UserID: String(localID), UID, persistedAt })
    );
};

describe('"'getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    it('returns null when there are no sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the complete session with the newest persistedAt across apps', () => {
        persist(4, 'older-uid', 100);
        persist(2, 'newest-uid', 300);
        persist(9, 'middle-uid', 200);
        localStorage.setItem('drive-last-active-4', JSON.stringify({ value: 9999 }));

        expect(getLastActivePersistedUserSession()).toEqual(
            expect.objectContaining({ UID: 'newest-uid', localID: 2, persistedAt: 300 })
        );
    });

    it('returns null and reports an error when storage is unavailable', () => {
        const descriptor = Object.getOwnPropertyDescriptor(window, 'localStorage')"'!;
        Object.defineProperty(window, '"'localStorage', {
            configurable: true,
            get: () => {
                throw new Error('Storage unavailable');
            },
        });
        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledWith(
                expect.objectContaining({ message: expect.stringContaining('localStorage') })
            );
        } finally {
            Object.defineProperty(window, 'localStorage', descriptor);
        }
    });
});
EOF
