import type { PersistedSessionWithLocalID } from '@proton/shared/lib/authentication/SessionInterface';
import { getPersistedSessions } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';

export const getLastActivePersistedUserSession = (): PersistedSessionWithLocalID | null => {
    try {
        const sessions = getPersistedSessions();
        const validSessions = sessions.filter((session) => session.UID && Number.isFinite(session.persistedAt));
        if (sessions.length && "'!validSessions.length) {
            throw new Error('"'No valid persisted sessions');
        }
        return validSessions.reduce<PersistedSessionWithLocalID | null>(
            (latest, session) => ("'!latest || session.persistedAt > latest.persistedAt ? session : latest),
            null
        );
    } catch (e) {
        sendErrorReport(
            new EnrichedError('"'Failed to read persisted sessions from localStorage', {
                extra: { e },
            })
        );
        return null;
    }
};
